# Great! Girth is 7. Now check 3-colorability
edge_list = [(0, 1), (0, 12), (0, 23), (1, 2), (1, 8), (2, 3), (2, 19), (3, 4), (3, 15), (4, 5), (4, 11), (5, 6), (5, 22), (6, 7), (6, 18), (7, 8), (7, 14), (8, 9), (9, 10), (9, 21), (10, 11), (10, 17), (11, 12), (12, 13), (13, 14), (13, 20), (14, 15), (15, 16), (16, 17), (16, 23), (17, 18), (18, 19), (19, 20), (20, 21), (21, 22), (22, 23)]

n = 24
adj = [[] for _ in range(n)]
for u, v in edge_list:
    adj[u].append(v)
    adj[v].append(u)

def is_3_colorable(adj, n):
    color = [-1] * n

    def backtrack(node):
        if node == n:
            return True
        for c in range(3):
            valid = all(color[nb] != c for nb in adj[node])
            if valid:
                color[node] = c
                if backtrack(node + 1):
                    return True
                color[node] = -1
        return False

    return backtrack(0), color

sat, coloring = is_3_colorable(adj, n)
print(f"Is 3-colorable: {sat}")
if sat:
    print(f"Coloring: {coloring}")
    # Verify
    valid = True
    for u, v in edge_list:
        if coloring[u] == coloring[v]:
            print(f"ERROR: edge ({u},{v}) has same color {coloring[u]}")
            valid = False
    if valid:
        print("Coloring verified correct!")
